// @ts-strict-ignore
import styles from "./quantity-selector.module.less";
import { SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { multipleClassNames } from "@/core/helpers";
import { IconName } from "@/core/components/primitives/icon/icon";

export type QuantitySelectorProps = {
  isDisabled?: boolean;
  quantity: number;
  minQuantity?: number;
  maxQuantity?: number;
  isMaxQuantityReached?: boolean;
  onQuantityChanged: (quantity: number) => void;
  wrapperClassName?: string;
  descriptionClassName?: string;
  classNameLeftButton?: string;
  classNameRightButton?: string;
  quantityClassName?: string;
  perPerson?: string;
  quantityPresentatorOverride?: string;
  /**Used to show a different icon for the negative button when the quantity is at one  */
  removeQuantityIconOverride?: IconName;
  description?: string;
  testIds?: [string, string];
};

const QuantitySelector = ({
  isDisabled,
  quantity,
  minQuantity = 0,
  maxQuantity,
  isMaxQuantityReached,
  onQuantityChanged,
  wrapperClassName,
  classNameLeftButton,
  classNameRightButton,
  quantityClassName,
  perPerson,
  quantityPresentatorOverride,
  removeQuantityIconOverride,
  description,
  testIds,
}: QuantitySelectorProps) => {
  const { t } = useTranslation();

  const _isMinQuantityReached = typeof minQuantity === "number" && quantity <= minQuantity;
  const _isMaxQuantityReached = (typeof maxQuantity === "number" && quantity >= maxQuantity) || isMaxQuantityReached;

  const clamp = (val: number) => {
    let next = val;

    if (typeof minQuantity === "number" && next < minQuantity) {
      next = minQuantity;
    }
    if (typeof maxQuantity === "number" && next > maxQuantity) {
      next = maxQuantity;
    }

    return next;
  };

  const onClickChangeQuantity = (modifiedQuantity: number) => {
    if (!(onQuantityChanged && typeof onQuantityChanged === "function")) {
      return;
    }
    const next = clamp(modifiedQuantity);

    if (next === quantity) {
      return;
    }
    onQuantityChanged(next);
  };

  const isDecreaseDisabled = isDisabled || _isMinQuantityReached;
  const isIncreaseDisabled = isDisabled || _isMaxQuantityReached;

  const quantityString = quantityPresentatorOverride ?? `${quantity} ${perPerson ?? ""} ${description ?? ""}`.trim();

  return (
    <div className={multipleClassNames(wrapperClassName, styles.wrapper)}>
      <SecondaryButton
        isDisabled={isDecreaseDisabled}
        iconCenterNew={removeQuantityIconOverride && quantity === 1 ? removeQuantityIconOverride : "remove"}
        ariaLabel={t("decrease") + " " + t("quantity")}
        onClick={() => onClickChangeQuantity(quantity - 1)}
        className={multipleClassNames(classNameLeftButton, styles.button, styles.buttonDecrease)}
        testId={testIds && testIds[0]}
      />
      <span className={multipleClassNames(quantityClassName, styles.textWrapper, "subtitle")}>{quantityString}</span>
      <SecondaryButton
        isDisabled={isIncreaseDisabled}
        iconCenterNew="add"
        ariaLabel={t("increase") + " " + t("quantity")}
        onClick={() => onClickChangeQuantity(quantity + 1)}
        className={multipleClassNames(classNameRightButton, styles.button, styles.buttonIncrease)}
        testId={testIds && testIds[1]}
      />
    </div>
  );
};

export default QuantitySelector;
