import styles from "./quantity-selector-styled.module.less";
import { multipleClassNames } from "@/core/helpers/string-helper";
import QuantitySelector, {
  QuantitySelectorProps,
} from "@/core/components/primitives/quantity-selector/quantity-selector";

type QuantitySelectorStyledProps = {
  parentClassName?: string;
  wrapperClassName?: string;
  classNameLeftButton?: string;
  classNameRightButton?: string;
  quantityClassName?: string;
  label?: string;
  sublabel?: string;
  isFullWidth?: boolean;
  onQuantityChange: (quantity: number) => void;
} & Pick<
  QuantitySelectorProps,
  //These are props to pass down to QuantitySelector as is
  | "isDisabled"
  | "quantity"
  | "minQuantity"
  | "maxQuantity"
  | "quantityPresentatorOverride"
  | "removeQuantityIconOverride"
>;

const QuantitySelectorStyled = ({
  parentClassName,
  wrapperClassName,
  classNameLeftButton,
  classNameRightButton,
  quantityClassName,
  label,
  sublabel,
  isDisabled,
  isFullWidth,
  quantity,
  maxQuantity,
  minQuantity,
  quantityPresentatorOverride,
  removeQuantityIconOverride,
  onQuantityChange,
}: QuantitySelectorStyledProps) => {
  return (
    <div className={multipleClassNames(styles.wrapper, parentClassName)}>
      {label && (
        <label className={styles.descriptionWrapper}>
          <span className={`heading-xs ${styles.label}`}>{label}</span>
          {sublabel && <p className={`p_small ${styles.sublabel}`}>{sublabel}</p>}
        </label>
      )}
      <QuantitySelector
        wrapperClassName={multipleClassNames(
          wrapperClassName,
          styles.quantitySelector,
          isFullWidth && styles.fullWidth,
        )}
        quantityClassName={multipleClassNames(
          quantityClassName,
          isFullWidth ? styles.quantityDisplayFullWidth : styles.quantityDisplay,
        )}
        classNameLeftButton={multipleClassNames(classNameLeftButton, styles.leftButton)}
        classNameRightButton={multipleClassNames(classNameRightButton, styles.rightButton)}
        isDisabled={isDisabled}
        quantity={quantity}
        maxQuantity={maxQuantity}
        minQuantity={minQuantity}
        quantityPresentatorOverride={quantityPresentatorOverride}
        removeQuantityIconOverride={removeQuantityIconOverride}
        onQuantityChanged={onQuantityChange}
        testIds={[`decrease-button-${label}`, `increase-button-${label}`]}
      />
    </div>
  );
};

export default QuantitySelectorStyled;
